import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { 
    FaCalendarAlt, FaCheck, FaPlus, FaSync, 
    FaSave, FaComment, FaEye, FaBullseye, FaUsers,
    FaSpinner, FaFire, FaTasks, FaHeart, FaChartLine,
    FaRocket
} from 'react-icons/fa';
import { motion, AnimatePresence } from 'framer-motion';
import axios from 'axios';
import toast from 'react-hot-toast';

const DailyTracker = () => {
    const { user, token } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [selectedDay, setSelectedDay] = useState(null);
    const [loading, setLoading] = useState(true);
    const [creating, setCreating] = useState(false);
    const [selectedTask, setSelectedTask] = useState(null);
    const [taskNote, setTaskNote] = useState('');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [showHistory, setShowHistory] = useState(false);
    
    const today = new Date();
    const currentMonth = today.getMonth();
    const currentYear = today.getFullYear();
    const currentDay = today.getDate();
    
    const targetDate = new Date(2026, 10, 30);
    const daysRemaining = Math.max(0, Math.ceil((targetDate - today) / (1000 * 60 * 60 * 24)));
    
    const getDaysInMonth = (month, year) => {
        return new Date(year, month + 1, 0).getDate();
    };
    
    const daysInMonth = getDaysInMonth(currentMonth, currentYear);
    const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 
                        'July', 'August', 'September', 'October', 'November', 'December'];

    useEffect(() => {
        console.log("🟡 DailyTracker Mounted. User:", user);
        
        const safetyTimer = setTimeout(() => {
            if (loading) {
                console.warn("⚠️ DailyTracker: Safety timer triggered! Stopping loader.");
                setLoading(false);
            }
        }, 3000);

        if (user && token) {
            fetchTasks();
        } else {
            console.log("⏳ DailyTracker: Waiting for user context to load...");
        }

        return () => clearTimeout(safetyTimer);
    }, [user, token]);

    const fetchTasks = async () => {
        try {
            const response = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(response.data);
        } catch (error) {
            console.error('Failed to fetch tasks:', error);
            toast.error('Failed to load tasks');
        } finally {
            setLoading(false);
        }
    };

    const createTaskForDay = async (day) => {
        setCreating(true);
        try {
            const date = new Date(currentYear, currentMonth, day);
            const dateStr = date.toISOString().split('T')[0];
            
            const response = await axios.post(
                `http://localhost:8081/api/tasks/user/${user.id}/day/${day}?date=${dateStr}`,
                {},
                { 
                    headers: { 
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    } 
                }
            );
            setTasks([...tasks, response.data]);
            toast.success(`✅ Tasks created for ${monthNames[currentMonth]} ${day}`);
            return response.data;
        } catch (error) {
            console.error('Failed to create task:', error);
            toast.error('Failed to create tasks');
            return null;
        } finally {
            setCreating(false);
        }
    };

    const toggleTask = async (taskId, field) => {
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const updatedTask = { ...task, [field]: !task[field] };
        
        try {
            const response = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasks.map(t => t.id === taskId ? response.data : t));
            
            const isCompleted = updatedTask[field];
            if (isCompleted) {
                toast.success('✅ Alhamdulillah! Task completed!');
            } else {
                toast.info('Task marked as incomplete');
            }
        } catch (error) {
            console.error('Failed to update task:', error);
            toast.error('Failed to update task');
        }
    };

    const updateTaskNote = async (taskId, note) => {
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const updatedTask = { ...task, notes: note };
        
        try {
            const response = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasks.map(t => t.id === taskId ? response.data : t));
            toast.success('💾 Note saved!');
        } catch (error) {
            console.error('Failed to save note:', error);
            toast.error('Failed to save note');
        }
    };

    const handleDayClick = async (day) => {
        setSelectedDay(day);
        const dayTasks = tasks.filter(task => task.day === day);
        if (dayTasks.length === 0 && !creating) {
            await createTaskForDay(day);
        }
    };

    const handleTaskClick = (task, field) => {
        const labels = {
            javaCompleted: 'Java',
            leetcodeCompleted: 'LeetCode',
            dsaCompleted: 'DSA/OOP',
            sqlCompleted: 'SQL/APIs',
            projectCompleted: 'Project',
            githubCompleted: 'GitHub/Portfolio'
        };
        setSelectedTask({ task, field, label: labels[field] });
        setTaskNote(task.notes || '');
        setIsModalOpen(true);
    };

    const saveNote = () => {
        if (selectedTask) {
            updateTaskNote(selectedTask.task.id, taskNote);
            setIsModalOpen(false);
        }
    };

    const getDayTasks = (day) => tasks.filter(task => task.day === day);

    const getDayStatus = (day) => {
        const dayTasks = getDayTasks(day);
        if (dayTasks.length === 0) return 'empty';
        const completed = dayTasks.filter(t => t.overallCompleted).length;
        if (completed === dayTasks.length) return 'done';
        if (completed > 0) return 'partial';
        return 'started';
    };

    const tasksWithNotes = tasks.filter(t => t.notes && t.notes.trim() !== '');
    const totalCompleted = tasks.filter(t => t.overallCompleted).length;
    const totalTasks = tasks.length;
    const progressPercent = totalTasks > 0 ? Math.round((totalCompleted / totalTasks) * 100) : 0;

    const getStatusColor = (status) => {
        switch(status) {
            case 'done': return '#10b981'; // Green
            case 'partial': return '#f59e0b'; // Orange
            case 'started': return '#6366f1'; // Purple/Blue to match your dashboard
            default: return '#e5e7eb'; // Grey
        }
    };

    if (loading) {
        return (
            <div className="d-flex justify-content-center align-items-center" style={{ height: '60vh' }}>
                <div className="text-center">
                    <FaSpinner className="fa-spin text-primary" size={40} />
                    <p className="text-muted mt-3">Loading your dashboard...</p>
                </div>
            </div>
        );
    }

    const taskLabels = [
        { key: 'javaCompleted', label: 'Java (1.5h)', icon: '☕' },
        { key: 'leetcodeCompleted', label: 'LeetCode (1+)', icon: '💻' },
        { key: 'dsaCompleted', label: 'DSA/OOP (1h)', icon: '📊' },
        { key: 'sqlCompleted', label: 'SQL/APIs (1h)', icon: '🗄️' },
        { key: 'projectCompleted', label: 'Project (2-3h)', icon: '🚀' },
        { key: 'githubCompleted', label: 'GitHub/Portfolio', icon: '📁' }
    ];

    const calendarDays = [];
    for (let day = 1; day <= daysInMonth; day++) {
        calendarDays.push(day);
    }

    const weekDays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    return (
        <div className="container-fluid p-0">
            {/* Notes Modal */}
            <AnimatePresence>
                {isModalOpen && selectedTask && (
                    <motion.div 
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="modal show d-block" 
                        style={{ backgroundColor: 'rgba(0,0,0,0.5)', zIndex: 1050 }}
                        tabIndex="-1"
                    >
                        <div className="modal-dialog modal-dialog-centered modal-md">
                            <motion.div 
                                initial={{ scale: 0.9, y: 20 }}
                                animate={{ scale: 1, y: 0 }}
                                exit={{ scale: 0.9, y: 20 }}
                                className="modal-content rounded-4 border-0 shadow-lg"
                            >
                                <div className="modal-header border-0 pb-0">
                                    <div>
                                        <h5 className="modal-title fw-bold">
                                            <span className="text-primary">{selectedTask.label}</span>
                                            <span className="text-muted fs-6 fw-normal ms-2">
                                                - {monthNames[currentMonth]} {selectedTask.task.day}
                                            </span>
                                        </h5>
                                        <p className="text-muted small mb-0">📝 Add your learning notes</p>
                                    </div>
                                    <button 
                                        onClick={() => setIsModalOpen(false)}
                                        className="btn-close"
                                    />
                                </div>
                                <div className="modal-body pt-3">
                                    <div className="mb-3">
                                        <label className="form-label fw-semibold small">
                                            <FaComment className="me-1 text-primary" /> What did you learn today?
                                        </label>
                                        <textarea
                                            value={taskNote}
                                            onChange={(e) => setTaskNote(e.target.value)}
                                            className="form-control rounded-3"
                                            rows="5"
                                            placeholder="📝 Write what you studied, concepts learned, problems solved..."
                                            style={{ resize: 'none' }}
                                        />
                                    </div>
                                </div>
                                <div className="modal-footer border-0 pt-0">
                                    <button
                                        onClick={() => setIsModalOpen(false)}
                                        className="btn btn-light rounded-pill px-4"
                                    >
                                        Cancel
                                    </button>
                                    <button
                                        onClick={saveNote}
                                        className="btn btn-primary rounded-pill px-4"
                                    >
                                        <FaSave className="me-2" /> Save Note
                                    </button>
                                </div>
                            </motion.div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Professional Hero Header */}
            <motion.div 
                initial={{ opacity: 0, y: -20 }}
                animate={{ opacity: 1, y: 0 }}
                className="hero-gradient mb-4 p-4 rounded-4 shadow-sm"
            >
                <div className="d-flex flex-wrap justify-content-between align-items-center text-white">
                    <div className="d-flex align-items-center gap-3">
                        <div className="bg-white bg-opacity-20 p-3 rounded-4">
                            <FaRocket size={28} className="text-white" />
                        </div>
                        <div>
                            <h4 className="fw-bold mb-0 fs-3">
                                📅 {monthNames[currentMonth]} {currentYear}
                            </h4>
                            <div className="d-flex gap-3 text-white-50 small">
                                <span>Today: <strong className="text-white">{currentDay} {monthNames[currentMonth]}</strong></span>
                                <span className="text-white-50">•</span>
                                <span className="fw-semibold">
                                    <FaBullseye className="me-1" /> {daysRemaining} days left
                                </span>
                            </div>
                        </div>
                    </div>
                    <div className="d-flex gap-2 mt-2 mt-sm-0">
                        <div className="bg-white bg-opacity-20 rounded-pill px-3 py-2 d-flex align-items-center gap-2">
                            <FaChartLine className="text-white" />
                            <span className="fw-semibold">{progressPercent}%</span>
                            <span className="small text-white-50">Progress</span>
                        </div>
                        <button 
                            onClick={fetchTasks}
                            className="btn btn-light rounded-pill px-3 fw-semibold"
                        >
                            <FaSync className="me-1" /> Refresh
                        </button>
                    </div>
                </div>
            </motion.div>

            {/* Progress Bar */}
            <motion.div 
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                className="mb-4 bg-white rounded-4 shadow-sm p-3"
            >
                <div className="d-flex justify-content-between align-items-center mb-1">
                    <span className="text-muted small fw-semibold">📊 Overall Progress</span>
                    <span className="fw-bold text-primary">{progressPercent}%</span>
                </div>
                <div className="progress" style={{ height: '8px', background: '#e9ecef', borderRadius: '10px' }}>
                    <motion.div 
                        initial={{ width: 0 }}
                        animate={{ width: `${progressPercent}%` }}
                        transition={{ duration: 0.8, ease: "easeOut" }}
                        className="progress-bar bg-gradient-to-r from-primary to-purple-600"
                        style={{ borderRadius: '10px' }}
                    />
                </div>
            </motion.div>

            {/* Calendar + Tasks Grid */}
            <div className="row g-4">
                {/* Calendar Section */}
                <div className="col-lg-8">
                    <motion.div 
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        className="bg-white rounded-4 shadow-sm p-4"
                    >
                        <div className="d-flex justify-content-between align-items-center mb-3">
                            <h6 className="fw-bold mb-0 text-dark">📆 Monthly Calendar</h6>
                            <div className="d-flex gap-2">
                                <span className="badge bg-success text-white rounded-pill px-2">✅ Done</span>
                                <span className="badge bg-warning text-white rounded-pill px-2">🟡 Partial</span>
                                <span className="badge bg-primary text-white rounded-pill px-2">🔵 Started</span>
                                <span className="badge bg-light text-dark rounded-pill px-2">⬜ Empty</span>
                            </div>
                        </div>
                        
                        {/* Grid Wrapper to make it look professional and aligned */}
                        <div className="row g-1">
                            {weekDays.map(day => (
                                <div key={day} className="col text-center text-muted small fw-semibold py-2 bg-light rounded-3 mx-1">
                                    {day}
                                </div>
                            ))}
                            
                            {/* Spacing for dates */}
                            {calendarDays.map((day) => {
                                const status = getDayStatus(day);
                                const bgColor = getStatusColor(status);
                                const isSelected = selectedDay === day;
                                const isToday = day === currentDay && currentMonth === new Date().getMonth();
                                
                                return (
                                    <div key={day} className="col p-1">
                                        <motion.button
                                            whileHover={{ scale: 1.05 }}
                                            transition={{ type: "spring", stiffness: 300 }}
                                            onClick={() => handleDayClick(day)}
                                            className="w-100 btn rounded-3 fw-semibold position-relative transition-all"
                                            style={{ 
                                                aspectRatio: '1/1',
                                                fontSize: '14px',
                                                padding: '4px',
                                                backgroundColor: bgColor,
                                                color: status === 'empty' ? '#6b7280' : 'white',
                                                border: isSelected ? '3px solid #6366f1' : 'none',
                                                boxShadow: isSelected ? '0 4px 6px rgba(99,102,241,0.3)' : 'none',
                                                transition: 'all 0.2s ease'
                                            }}
                                        >
                                            {day}
                                            {isToday && (
                                                <span className="position-absolute top-0 start-100 translate-middle p-1 bg-danger rounded-circle" style={{ width: '8px', height: '8px' }} />
                                            )}
                                        </motion.button>
                                    </div>
                                );
                            })}
                        </div>
                    </motion.div>
                </div>

                {/* Professional Tasks Section */}
                <div className="col-lg-4">
                    <motion.div 
                        initial={{ opacity: 0, x: 20 }}
                        animate={{ opacity: 1, x: 0 }}
                        className="bg-white rounded-4 shadow-sm p-4 border border-light"
                        style={{ minHeight: '400px' }}
                    >
                        <div className="d-flex justify-content-between align-items-center border-bottom pb-3 mb-3">
                            <h6 className="fw-bold mb-0 text-dark">
                                <FaTasks className="me-2 text-primary" />
                                {selectedDay ? `Day ${selectedDay} Tasks` : 'Select a Day'}
                            </h6>
                            {selectedDay && (
                                <span className="badge bg-primary bg-opacity-10 text-primary rounded-pill px-3 py-2">
                                    {getDayTasks(selectedDay).length} items
                                </span>
                            )}
                        </div>
                        
                        {selectedDay ? (
                            <div className="d-flex flex-column gap-2">
                                {taskLabels.map(({ key, label, icon }) => {
                                    const dayTasks = getDayTasks(selectedDay);
                                    const task = dayTasks[0];
                                    const isCompleted = task ? task[key] : false;
                                    const hasNote = task?.notes && task.notes.trim() !== '';
                                    
                                    return (
                                        <motion.div
                                            key={key}
                                            whileHover={{ scale: 1.01 }}
                                            transition={{ type: "spring", stiffness: 400 }}
                                            className={`d-flex justify-content-between align-items-center p-3 rounded-3 transition-all cursor-pointer ${
                                                isCompleted 
                                                    ? 'bg-success bg-opacity-10 border border-success' 
                                                    : 'bg-light border border-secondary'
                                            }`}
                                            onClick={() => task && handleTaskClick(task, key)}
                                        >
                                            <div className="d-flex align-items-center gap-2">
                                                <span style={{ fontSize: '20px' }}>{icon}</span>
                                                <div>
                                                    <span className={`small fw-medium ${isCompleted ? 'text-muted text-decoration-line-through' : 'text-dark'}`}>
                                                        {label}
                                                    </span>
                                                    {hasNote && (
                                                        <span className="badge bg-info text-white rounded-pill ms-1" style={{ fontSize: '8px' }}>
                                                            <FaComment size={10} /> note
                                                        </span>
                                                    )}
                                                </div>
                                            </div>
                                            <button
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    task && toggleTask(task.id, key);
                                                }}
                                                className={`btn rounded-pill px-3 py-1 fw-semibold ${
                                                    isCompleted 
                                                        ? 'btn-success' 
                                                        : 'btn-outline-primary'
                                                }`}
                                                style={{ fontSize: '12px' }}
                                            >
                                                {isCompleted ? '✅ Done' : 'Mark Done'}
                                            </button>
                                        </motion.div>
                                    );
                                })}
                                
                                {getDayTasks(selectedDay).length === 0 && !creating && (
                                    <motion.div 
                                        initial={{ opacity: 0 }}
                                        animate={{ opacity: 1 }}
                                        className="text-center py-5 bg-light rounded-4 border-dashed border-2 border-secondary"
                                    >
                                        <div className="bg-primary bg-opacity-10 rounded-circle d-flex align-items-center justify-content-center mx-auto mb-3" style={{ width: '64px', height: '64px' }}>
                                            <FaPlus size={24} className="text-primary" />
                                        </div>
                                        <p className="text-muted small mb-3 fw-semibold">🚀 No tasks for this day</p>
                                        <button
                                            onClick={() => handleDayClick(selectedDay)}
                                            className="btn btn-primary rounded-pill px-4 fw-semibold"
                                        >
                                            <FaPlus className="me-2" /> Generate Tasks
                                        </button>
                                    </motion.div>
                                )}
                                
                                {creating && (
                                    <div className="text-center py-5">
                                        <FaSpinner className="fa-spin text-primary" size={32} />
                                        <p className="text-muted small mt-2">Generating your tasks...</p>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="d-flex align-items-center justify-content-center py-5 text-muted bg-light rounded-4">
                                <div className="text-center">
                                    <FaCalendarAlt size={48} className="text-gray-400 mb-3" />
                                    <p className="small fw-semibold text-dark">👆 Pick a date from the calendar</p>
                                    <p className="small">Generate your daily roadmap tasks</p>
                                </div>
                            </div>
                        )}
                    </motion.div>
                </div>
            </div>
        </div>
    );
};

export default DailyTracker;
